/* Calendar, archives and race detail from the established public ACC event API. */
(() => {
 const root=document.querySelector('#results'),page=document.body.dataset.page,lang=document.documentElement.lang;
 if(!root||!['calendar','archives','event'].includes(page))return;
 const base=document.querySelector('meta[name="atx-base"]')?.content||'/atxracing/';
 const url='https://twjpjzalyvbsdpbzhqln.supabase.co/functions/v1/public-event';
 const dictionary={
 fr:{loading:'Chargement des courses…',error:'Les courses sont momentanément indisponibles.',empty:'Aucune course publiée pour cette sélection.',register:'S’inscrire sur SimGrid',results:'Résultats officiels',teams:'Équipes',driver:'Pilote',team:'Équipe',car:'Voiture',lap:'Meilleur tour',points:'Points',date:'Date',details:'Voir la course',archived:'Course terminée',upcoming:'Course programmée'},
 en:{loading:'Loading races…',error:'Races are temporarily unavailable.',empty:'No race published for this selection.',register:'Register on SimGrid',results:'Official results',teams:'Teams',driver:'Driver',team:'Team',car:'Car',lap:'Best lap',points:'Points',date:'Date',details:'View race',archived:'Completed race',upcoming:'Upcoming race'},
 de:{loading:'Rennen werden geladen…',error:'Rennen sind vorübergehend nicht verfügbar.',empty:'Keine Rennen für diese Auswahl veröffentlicht.',register:'Auf SimGrid anmelden',results:'Offizielle Ergebnisse',teams:'Teams',driver:'Fahrer',team:'Team',car:'Fahrzeug',lap:'Beste Runde',points:'Punkte',date:'Datum',details:'Rennen ansehen',archived:'Abgeschlossenes Rennen',upcoming:'Geplantes Rennen'},
 it:{loading:'Caricamento gare…',error:'Le gare sono temporaneamente indisponibili.',empty:'Nessuna gara pubblicata per questa selezione.',register:'Iscriviti su SimGrid',results:'Risultati ufficiali',teams:'Squadre',driver:'Pilota',team:'Squadra',car:'Auto',lap:'Miglior giro',points:'Punti',date:'Data',details:'Vedi gara',archived:'Gara conclusa',upcoming:'Gara in programma'},
 es:{loading:'Cargando carreras…',error:'Las carreras no están disponibles temporalmente.',empty:'No hay carreras publicadas para esta selección.',register:'Inscribirse en SimGrid',results:'Resultados oficiales',teams:'Equipos',driver:'Piloto',team:'Equipo',car:'Coche',lap:'Mejor vuelta',points:'Puntos',date:'Fecha',details:'Ver carrera',archived:'Carrera terminada',upcoming:'Próxima carrera'}
 }[lang];
 const el=(tag,cls,txt)=>{const x=document.createElement(tag);if(cls)x.className=cls;if(txt!==undefined)x.textContent=String(txt);return x};
 const time=stamp=>stamp?new Intl.DateTimeFormat(lang,{dateStyle:'long',timeStyle:'short',timeZone:'Europe/Brussels'}).format(new Date(stamp)):'—';
 const lap=ms=>ms>0?`${Math.floor(ms/60000)}:${String(Math.floor(ms/1000)%60).padStart(2,'0')}.${String(ms%1000).padStart(3,'0')}`:'—';
 const external=raw=>{try{const parsed=new URL(raw);return parsed.protocol==='https:'?parsed.href:null}catch{return null}};
 const type=e=>{const s=[e.server_name,e.title_fr,e.title_en,e.event_type].join(' ').toUpperCase();return /BALLADE\s+ATX/.test(s)?'BA':/\bWGT\b|WORLD\s?GT|ENDURANCE|SPRINT/.test(s)?'WGT':/\bDR\b|DAILY\s?RACE/.test(s)?'DR':null};
 const href=e=>base+lang+'/acc/event.html?slug='+encodeURIComponent(e.slug);
 const name=e=>e['title_'+lang]||e.title_en||e.title_fr||e.circuit_name||'ATXRACING';
 function tile(e){const a=el('a','event-tile');a.href=href(e);const poster=el('span','event-poster');const image=external(e.image_url);if(image){const img=el('img');img.src=image;img.alt='';img.loading='lazy';img.onerror=()=>img.remove();poster.append(img)}const body=el('span','event-copy');body.append(el('small','meta',(type(e)||'ACC')+' / '+time(e.starts_at)),el('strong','',name(e)),el('span','',e.circuit_name||''),el('small','',dictionary.details+' ↗'));a.append(poster,body);return a}
 function rows(headers,values){const wrap=el('div','ranking-table-wrap'),table=el('table','ranking-table'),head=el('thead'),tr=el('tr'),tbody=el('tbody');headers.forEach(h=>tr.append(el('th','',h)));head.append(tr);values.forEach(row=>{const tr=el('tr');row.forEach(value=>tr.append(el('td','',value??'—')));tbody.append(tr)});table.append(head,tbody);wrap.append(table);return wrap}
 async function load(){root.replaceChildren(el('p','loading',dictionary.loading));try{
  if(page==='event'){const slug=new URLSearchParams(location.search).get('slug');if(!slug||!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(slug)){root.replaceChildren(el('p','empty',dictionary.empty));return}const response=await fetch(url+'?slug='+encodeURIComponent(slug));if(!response.ok)throw Error(response.status);const payload=await response.json(),e=payload.event;const container=el('article','event-detail'),visual=el('div','event-detail-visual');const photo=external(e.image_url);if(photo){const img=el('img');img.src=photo;img.alt='';visual.append(img)}container.append(visual,el('span','eyebrow',type(e)||'ACC'),el('h2','',name(e)),el('p','',e.circuit_name+' · '+time(e.starts_at)));if(external(e.simgrid_url)){const link=el('a','action',dictionary.register+' ↗');link.href=external(e.simgrid_url);link.target='_blank';link.rel='noopener noreferrer';container.append(link)}root.replaceChildren(container);
   const team=payload.team_results||[],drivers=payload.results||[];if(team.length){root.append(el('h2','event-results-heading',dictionary.teams),rows(['#',dictionary.team,dictionary.driver,dictionary.car,dictionary.points,dictionary.lap],team.map(r=>[r.finish_position,r.team_name,(r.members||[]).join(' / '),r.car_model_name,r.points,lap(r.best_lap_ms)])))}if(drivers.length){root.append(el('h2','event-results-heading',dictionary.results),rows(['#',dictionary.driver,dictionary.car,dictionary.points,dictionary.lap],drivers.map(r=>[r.finish_position,Array.isArray(r.driver)?r.driver[0]?.display_name:r.driver?.display_name,r.car_model_name,r.points,lap(r.best_lap_ms)])))}return}
  const response=await fetch(url);if(!response.ok)throw Error(response.status);const data=await response.json();const items=page==='archives'?(data.archives||[]):(data.events||[]);let active=new URLSearchParams(location.search).get('type')?.toUpperCase()||'ALL';const nav=document.querySelector('.event-categories');function render(){const filtered=items.filter(e=>active==='ALL'||type(e)===active);const grid=el('div','event-grid');filtered.forEach(e=>grid.append(tile(e)));root.replaceChildren(filtered.length?grid:el('p','empty',dictionary.empty));nav?.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.category===active)))}nav?.querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>{active=b.dataset.category;const query=new URLSearchParams(location.search);active==='ALL'?query.delete('type'):query.set('type',active);history.replaceState(null,'',location.pathname+(query.size?'?'+query:''));render()}));render()
 }catch{root.replaceChildren(el('p','empty',dictionary.error))}}
 load();
})();
